<?php
require_once __DIR__.'/includes/functions.php';
$id=safe_int($_GET['id']??0);$s=db()->prepare("SELECT p.*,c.name category_name,u.name farmer_name,f.verification_status,f.id farmer_public_id,(SELECT COALESCE(AVG(rating),0) FROM reviews r WHERE r.product_id=p.id AND r.status='visible') rating,(SELECT COUNT(*) FROM reviews r WHERE r.product_id=p.id AND r.status='visible') review_count FROM products p JOIN categories c ON c.id=p.category_id JOIN farmers f ON f.id=p.farmer_id JOIN users u ON u.id=f.user_id WHERE p.id=?");$s->execute([$id]);$product=$s->fetch();if(!$product){http_response_code(404);exit('Produto não encontrado');}$reviews=db()->prepare('SELECT r.*,u.name FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.product_id=? AND r.status="visible" ORDER BY r.created_at DESC LIMIT 6');$reviews->execute([$id]);$reviews=$reviews->fetchAll();$related=db()->prepare("SELECT p.*,c.name category_name,u.name farmer_name,f.verification_status FROM products p JOIN categories c ON c.id=p.category_id JOIN farmers f ON f.id=p.farmer_id JOIN users u ON u.id=f.user_id WHERE p.category_id=? AND p.id<>? AND p.status='active' AND c.is_active=1 ORDER BY p.sales_count DESC LIMIT 4");$related->execute([$product['category_id'],$id]);$related=$related->fetchAll();$available=$product['status']==='active'&&(float)$product['stock']>0&&(float)$product['stock']>=(float)$product['quantity_min'];$qMin=(float)$product['quantity_min']>0?(float)$product['quantity_min']:1;$qStep=in_array($product['unit'],['kg','litro'],true)?0.5:1;$fmtQ=fn($v)=>rtrim(rtrim(number_format((float)$v,2,'.',''),'0'),'.');$page_title=$product['name'];include __DIR__.'/includes/header.php';
?><section class="container py-5"><div class="row g-5"><div class="col-lg-6"><div class="product-detail-image"><img src="<?=e(get_product_image($product['main_image']))?>" onerror="this.src='<?=asset('img/product-placeholder.svg')?>'" alt="<?=e($product['name'])?>"></div></div><div class="col-lg-6"><div class="d-flex justify-content-between align-items-start"><div><span class="eyebrow"><?=e($product['category_name'])?></span><h1 class="display-5 fw-bold mt-2"><?=e($product['name'])?></h1></div><?php $fav=is_favorite(safe_int($product['id'])); ?><button class="favorite-btn large<?=$fav?' saved':''?>" data-favorite-product="<?=safe_int($product['id'])?>" aria-label="Favorito"><i class="bi bi-heart<?=$fav?'-fill':''?>"></i></button></div><div class="rating mb-3"><i class="bi bi-star-fill"></i> <?=number_format((float)$product['rating'],1)?> <span class="text-muted">(<?=safe_int($product['review_count'])?> avaliações)</span></div><div class="detail-price"><?=money($product['price'])?> <small>/ <?=e($product['unit'])?></small></div><div class="stock-line mb-4"><i class="bi bi-check-circle-fill"></i> <?=number_format((float)$product['stock'],2,',','.')?> <?=e($product['unit'])?> disponíveis</div><p class="lead-sm text-muted"><?=nl2br(e($product['description']))?></p><div class="detail-facts"><div><i class="bi bi-geo-alt"></i><span><small>Localização</small><strong><?=e($product['district']?:$product['locality']?:$product['province'])?></strong></span></div><div><i class="bi bi-person"></i><span><small>Agricultor</small><strong><a href="<?=base_path('agricultor.php?id='.$product['farmer_public_id'])?>"><?=e($product['farmer_name'])?> <?php if($product['verification_status']==='verified'): ?><i class="bi bi-patch-check-fill verified-text"></i><?php endif; ?></a></strong></span></div></div><div class="buy-box"><?php if(!$available): ?><div class="alert alert-warning mb-0"><i class="bi bi-exclamation-circle me-2"></i>Este produto não está disponível de momento.</div><?php else: ?><label class="form-label" for="product-quantity">Quantidade (<?=e($product['unit'])?>)<?php if($qMin>1): ?> <small class="text-muted">· mínimo <?=e($fmtQ($qMin))?></small><?php endif; ?></label><div class="input-group mb-3 quantity-control"><button type="button" data-qty-minus class="btn btn-light" aria-label="Diminuir">−</button><input id="product-quantity" type="number" class="form-control text-center" value="<?=e($fmtQ($qMin))?>" min="<?=e($fmtQ($qMin))?>" max="<?=e($fmtQ($product['stock']))?>" step="<?=e($qStep)?>"><button type="button" data-qty-plus class="btn btn-light" aria-label="Aumentar">+</button></div><div class="d-flex gap-2"><button class="btn btn-primary flex-grow-1" data-add-cart="<?=safe_int($product['id'])?>"><i class="bi bi-bag-plus me-2"></i>Adicionar ao carrinho</button><a class="btn btn-outline-primary" href="<?=base_path('carrinho.php')?>" aria-label="Ver carrinho"><i class="bi bi-bag"></i></a></div><?php endif; ?><?php if(logged_in()): ?><div class="mt-3 text-end"><a class="small text-muted" href="<?=base_path('denunciar.php?produto='.safe_int($product['id']))?>"><i class="bi bi-flag me-1"></i>Denunciar produto</a></div><?php endif; ?></div></div></div><div class="row mt-5"><div class="col-lg-8"><div class="content-card"><h4>Sobre este produto</h4><p><?=nl2br(e($product['description']))?></p><hr><h4 class="mt-4">Avaliações <span class="text-muted fs-6">(<?=safe_int($product['review_count'])?>)</span></h4><?php if(!$reviews): ?><p class="text-muted">Ainda não há avaliações para este produto.</p><?php else: foreach($reviews as $review): ?><div class="review-item"><div class="avatar-sm me-3"><?=e(mb_strtoupper(mb_substr($review['name'],0,1)))?></div><div><strong><?=e($review['name'])?></strong><div class="rating small"><?php for($i=1;$i<=5;$i++): ?><i class="bi bi-star<?=$i<=(int)$review['rating']?'-fill':''?>"></i><?php endfor; ?></div><p class="mb-0 text-muted"><?=e($review['comment'])?></p></div></div><?php endforeach; endif; ?></div></div></div></section><?php if($related): ?><section class="section-pad bg-soft"><div class="container"><h3 class="mb-4">Também pode gostar</h3><div class="row g-4"><?php foreach($related as $p): ?><div class="col-sm-6 col-lg-3"><?php include __DIR__.'/includes/product-card.php'; ?></div><?php endforeach; ?></div></div></section><?php endif; ?><?php include __DIR__.'/includes/footer.php'; ?>
